package byblos

// Orientation metadata (owner decision 2026-11-09, docs/guides/orientation.md):
// well-formed files get img2pdf's rotation (testdata/img2pdf/r4, 32 files);
// ambiguous ones get 0 and Ambiguous; defects img2pdf refuses are errors
// (testdata/img2pdf/r5, generated by r5/gen.py, with img2pdf's own result in
// its oracle.json).

import (
	"bytes"
	"encoding/binary"
	"encoding/json"
	"os"
	"strings"
	"testing"
)

func orientationOracle(t *testing.T, dir string) map[string]img2pdfEntry {
	t.Helper()
	raw, err := os.ReadFile("testdata/img2pdf/" + dir + "/oracle.json")
	if err != nil {
		t.Fatal(err)
	}
	var m map[string]img2pdfEntry
	if err := json.Unmarshal(raw, &m); err != nil {
		t.Fatal(err)
	}
	return m
}

// orientationOf is what a caller learns from a file: EXIFOrientation, and
// the Embed function's own refusal if it has one.
func orientationOf(t *testing.T, name string, data []byte) (Orientation, error) {
	t.Helper()
	o, err := EXIFOrientation(data, Limits{})
	switch {
	case err != nil || strings.HasPrefix(name, "rgba-"): // EmbedPNG refuses alpha
	case strings.HasSuffix(name, ".png"):
		_, _, err = EmbedPNG(data)
	default:
		_, _, err = EmbedJPEG(data)
	}
	return o, err
}

func TestOrientationRound4MatchesImg2pdf(t *testing.T) {
	for name, want := range orientationOracle(t, "r4") {
		data, err := os.ReadFile("testdata/img2pdf/r4/" + name)
		if err != nil {
			t.Fatal(err)
		}
		o, err := orientationOf(t, name, data)
		switch {
		case strings.HasPrefix(name, "rgba-") && want.Error != "" && !strings.Contains(want.Error, "TIFF"):
			// pHYs, page size: EmbedPNG's and BuildPDF's refusals, tested on the grey twin
		case strings.Contains(name, "aspect-big"): // BuildPDF's page size refusal, not orientation
		case want.Error != "":
			if err == nil {
				t.Errorf("%s: got %+v; img2pdf refuses (%s)", name, o, want.Error)
			}
		case name == "png-exif-afteridat6.png" || name == "rgba-png-exif-afteridat6.png":
			// img2pdf reads an eXIf after the IDAT; the rule does not.
			if err != nil || o != (Orientation{Ambiguous: true}) {
				t.Errorf("%s: got %+v, %v; want ambiguous", name, o, err)
			}
		case err != nil || o.Rotate != want.Rotate || o.Ambiguous:
			t.Errorf("%s: got %+v, %v; img2pdf wrote /Rotate %d", name, o, err, want.Rotate)
		}
	}
}

// ambiguous: rotation 0 and Ambiguous. Every other r5 entry img2pdf accepts
// is well formed and keeps img2pdf's rotation; the rest are parked.
var r5Ambiguous = map[string]bool{
	"pre-exif6-post-exif1.png": true, "pre-exif1-post-exif6.png": true,
	"pre-exifnoor-post-xmp6.png": true, "pre-exifnoor-post-text-exif6.png": true,
	"xmp6-then-text-empty.png": true, "text-xmp-noor-then-itxt-badutf8-6.png": true,
	"xmp6-then-itxt-corrupt-zlib.png": true, "itxt-rawprof-badlang6.png": true,
	"post-badtype-then-exif6.png": true, "post-exif6-badcrc.png": true,
}

func TestOrientationRound5(t *testing.T) {
	for name, want := range orientationOracle(t, "r5") {
		data, err := os.ReadFile("testdata/img2pdf/r5/" + name)
		if err != nil {
			t.Fatal(err)
		}
		o, err := orientationOf(t, name, data)
		base := strings.TrimPrefix(name, "rgba-")
		switch {
		case want.Error != "":
			if err == nil {
				t.Errorf("%s: got %+v; img2pdf refuses (%s)", name, o, want.Error)
			}
		case r5Ambiguous[base]:
			if err != nil || o != (Orientation{Ambiguous: true}) {
				t.Errorf("%s: got %+v, %v; want rotation 0 and ambiguous", name, o, err)
			}
		case err != nil || o.Rotate != want.Rotate || o.Ambiguous:
			t.Errorf("%s: got %+v, %v; img2pdf wrote /Rotate %d", name, o, err, want.Rotate)
		}
	}
}

// 70 zTXt chunks of 1 MB (a key nobody reads) are 70 MB of text: img2pdf
// refuses past 64 MiB, so does EXIFOrientation.
func TestOrientationTextOverBudgetParks(t *testing.T) {
	var chunks [][]byte
	for k := 0; k < 70; k++ {
		chunks = append(chunks, pngTextChunk("zTXt", "C"+string(rune('A'+k%26))+string(rune('a'+k/26)), make([]byte, 1000000)))
	}
	if _, err := EXIFOrientation(pngBeforeIDAT(t, chunks...), Limits{}); limitNamed(err) != "png-text-bytes" {
		t.Errorf("err = %v; want *LimitError png-text-bytes", err)
	}
}

// tiffOrient is a little-endian TIFF whose IFD0 has one SHORT Orientation
// entry per value.
func tiffOrient(vals ...uint16) []byte {
	b := []byte{'I', 'I', 42, 0, 8, 0, 0, 0}
	b = binary.LittleEndian.AppendUint16(b, uint16(len(vals)))
	for _, v := range vals {
		b = binary.LittleEndian.AppendUint16(b, 0x0112)
		b = binary.LittleEndian.AppendUint16(b, 3)
		b = binary.LittleEndian.AppendUint32(b, 1)
		b = binary.LittleEndian.AppendUint16(b, v)
		b = append(b, 0, 0)
	}
	return append(b, 0, 0, 0, 0)
}

func pngRaw(typ string, data []byte) []byte {
	var b bytes.Buffer
	writeHostileChunk(&b, typ, data)
	return b.Bytes()
}

func jpegApp1(payload ...[]byte) []byte {
	out := []byte{0xff, 0xd8}
	for _, p := range payload {
		out = append(out, 0xff, 0xe1, byte((len(p)+2)>>8), byte(len(p)+2))
		out = append(out, p...)
	}
	return append(out, 0xff, 0xd9)
}

func xmpPacket(o int) []byte {
	return append(append([]byte(nil), xapPrefix...), `<x:xmpmeta xmlns:x='adobe:ns:meta/'><rdf:Description xmlns:tiff='http://ns.adobe.com/tiff/1.0/'><tiff:Orientation>`+string(rune('0'+o))+`</tiff:Orientation></rdf:Description></x:xmpmeta>`...)
}

func exifSeg(vals ...uint16) []byte {
	return append(append([]byte(nil), exifPrefix...), tiffOrient(vals...)...)
}

// tiffDup is a little-endian TIFF whose IFD0 holds Orientation SHORT=6 and then a
// second 0x0112 entry of the given type, count and value/offset.
func tiffDup(typ uint16, count, val uint32) []byte {
	b := []byte{'I', 'I', 42, 0, 8, 0, 0, 0, 2, 0}
	b = append(b, 0x12, 0x01, 3, 0, 1, 0, 0, 0, 6, 0, 0, 0)
	b = append(b, 0x12, 0x01)
	b = binary.LittleEndian.AppendUint16(b, typ)
	b = binary.LittleEndian.AppendUint32(b, count)
	b = binary.LittleEndian.AppendUint32(b, val)
	return append(b, 0, 0, 0, 0)
}

// tiffDupAfterOutside is a little-endian TIFF whose IFD0 holds Orientation SHORT=6,
// an ASCII entry whose values lie outside the block, and then a second Orientation
// (SHORT=1), whole or, if truncated, cut after its tag, type and count.
func tiffDupAfterOutside(truncated bool) []byte {
	b := []byte{'I', 'I', 42, 0, 8, 0, 0, 0, 3, 0}
	b = append(b, 0x12, 0x01, 3, 0, 1, 0, 0, 0, 6, 0, 0, 0)
	b = append(b, 0x0f, 0x01, 2, 0, 100, 0, 0, 0, 0xf0, 0xff, 0, 0)
	b = append(b, 0x12, 0x01, 3, 0, 1, 0, 0, 0, 1, 0, 0, 0)
	if truncated {
		return b[:len(b)-6]
	}
	return append(b, 0, 0, 0, 0)
}

// Repeated orientation metadata is ambiguous whatever the values or the order
// (img2pdf follows Pillow and rotates by one of them).
func TestOrientationRepeatedSourcesAreAmbiguous(t *testing.T) {
	for name, data := range map[string][]byte{
		"two-xmp-1then6":   jpegApp1(xmpPacket(1), xmpPacket(6)),
		"two-xmp-6then1":   jpegApp1(xmpPacket(6), xmpPacket(1)),
		"two-xmp-6then6":   jpegApp1(xmpPacket(6), xmpPacket(6)),
		"two-exif-6then1":  jpegApp1(exifSeg(6), exifSeg(1)),
		"two-exif-1then6":  jpegApp1(exifSeg(1), exifSeg(6)),
		"jpeg-dup-tag":     jpegApp1(exifSeg(1, 6)),
		"jpeg-dup-tag-6-1": jpegApp1(exifSeg(6, 1)),
		"jpeg-dup-tag-6-6": jpegApp1(exifSeg(6, 6)),
		"png-dup-tag":      pngBeforeIDAT(t, pngRaw("eXIf", tiffOrient(1, 6))),
		// a repeat Pillow would skip (unknown type, no values, values outside the block) still counts.
		"jpeg-dup-badtype": jpegApp1(append(exifPrefix[:len(exifPrefix):len(exifPrefix)], tiffDup(99, 1, 0)...)),
		"jpeg-dup-count0":  jpegApp1(append(exifPrefix[:len(exifPrefix):len(exifPrefix)], tiffDup(3, 0, 0)...)),
		"jpeg-dup-outside": jpegApp1(append(exifPrefix[:len(exifPrefix):len(exifPrefix)], tiffDup(3, 100, 0xfff0)...)),
		// the repeat sits after an entry whose values lie outside the block, or is cut short by the block end.
		"jpeg-dup-after-outside": jpegApp1(append(exifPrefix[:len(exifPrefix):len(exifPrefix)], tiffDupAfterOutside(false)...)),
		"png-dup-after-outside":  pngBeforeIDAT(t, pngRaw("eXIf", tiffDupAfterOutside(false))),
		"jpeg-dup-truncated":     jpegApp1(append(exifPrefix[:len(exifPrefix):len(exifPrefix)], tiffDupAfterOutside(true)...)),
		"png-dup-truncated":      pngBeforeIDAT(t, pngRaw("eXIf", tiffDupAfterOutside(true))),
		"png-dup-badtype":        pngBeforeIDAT(t, pngRaw("eXIf", tiffDup(99, 1, 0))),
		"png-dup-count0":         pngBeforeIDAT(t, pngRaw("eXIf", tiffDup(3, 0, 0))),
	} {
		o, err := EXIFOrientation(data, Limits{})
		if err != nil || o != (Orientation{Ambiguous: true}) {
			t.Errorf("%s: got %+v, %v; want rotation 0 and ambiguous", name, o, err)
		}
	}
	// one source each stays Pillow's.
	if o, err := EXIFOrientation(jpegApp1(exifSeg(6), xmpPacket(6)), Limits{}); err != nil || o != (Orientation{Rotate: 90}) {
		t.Errorf("single sources: got %+v, %v; want 90", o, err)
	}
}
